/// <summary>
/// MPJ-21310 DEVOPS 34618
/// Responsible for dealing with item substitution logic.
/// </summary>
class METSalesItemSubstitution
{
    // ***** WIP *****

    // NB messages for the 'verbose' log will not be labelled as they're intended
    // for internal/debugging use only, and used to help document the code.
    
    // - If an 'Always' sub was applied, should we check for the other types
    //   at point of reservation?

    SalesLine                               salesLine;
    InventDim                               inventDim;
    SalesTable                              salesTable;

    METSalesItemSubstitutionEventSource     eventSource;
    boolean                                 interactive;  
    boolean                                 verboseLogging;
    METSalesItemSubstitutionAccountRelation substitutionGroup;
    boolean                                 itemReplaced;


}

Method.Source:
    public boolean run()
    {
        boolean ret;

        if(!CustParameters::find().METSubstitutionEnabled)
        {
            // Subs not enabled at legal-entity level.
            return true;
        }

        if(!salesLine.metSubstitutionsActive())
        {
            // Subs not applicable to this line.
            return true;
        }

        if(CustParameters::find().METSubstitutionVerboseLogging)
        {
            // At this point sales line has no RecID / Lot ID, but we're still
            // recording verbose log entries against it. Use a temporary identifier
            // against the log records then switch the reference over to lot ID
            // when the record is eventually saved.
            this.verboseLogging                             = true;
            salesLine.METSubstitutionVerboseLogReference    = newGuid();
        }

        // *** tbd, may define a separate 'substitution group'. For now 
        // we're using the customer group.
        substitutionGroup = salesTable.custTable_CustAccount().CustGroup;   

        ttsbegin;

        this.verboseInfo(funcName());
        this.verboseInfo(strFmt('Event source is %1', this.eventSource));        

        switch(this.eventSource)
        {
            case METSalesItemSubstitutionEventSource::Creation:
                ret = this.checkSalesLineAtCreation();
                break;
            case METSalesItemSubstitutionEventSource::Reservation:
                ret = this.checkSalesLineAtReservation();
                break;
            default:
                throw error(strFmt("Unknown substitution event source '%1' in %2",
                    this.eventSource,
                    funcName()));
        }

        if(ret)
        {
            if(itemReplaced)
            {
                salesLine.itemIdChanged();
                this.updateQuantity();
               
                // ** TODO "Product number" not refreshing on form.

                this.verboseInfo(strFmt('Item "%1" replaced with "%2"',
                    salesLine.METSubstituteOriginalItemID,
                    salesLine.METSubstituteReplacementItemID));
            }
        }

        ttscommit;

        return true;
    }

    /// <summary>
    /// Check / apply substitutes at point of order line reservation
    /// </summary>
    /// <returns>Validation result.</returns>
    protected boolean checkSalesLineAtReservation()
    {
        boolean ret = true;

        if(!salesLine.selectForUpdate())
        {
            throw error(strFmt("Sales line must be selected for update"));
        }

        if(!salesLine.InventTransId)
        {
            throw error(strFmt("%1 can only be called when the sales order line has already been saved",
                funcName()));
        }

        this.verboseInfo(strFmt('Checking line item %1 (Lot ID %2)',
            salesLine.ItemId,
            salesLine.InventTransId));

        if(salesLine.METSubstitutionType != METSalesItemSubstitutionType::None)
        {
            // Sub already applied.
            // TODO confirm whether reservation checks should be made in addition
            // to any replacements made at the point of line creation.
            this.verboseInfo("Line has already had replacements applied");
            return true;
        }

        Qty onHandQty = this.queryOnHandQty(salesLine.ItemId, inventDim);
        if(onHandQty < salesLine.QtyOrdered)
        {
            // Insufficient qty ("OOS")
            this.verboseInfo(strFmt('On-hand qty of %1 is less than ordered quantity of %2',
                onHandQty,
                salesLine.QtyOrdered));
            
            METSalesItemSubstitute itemSubNever = this.findSalesItemSubstitute(
                salesLine.ItemId, 
                METSalesItemSubstitutionCode::Never);
            if(itemSubNever)
            {
                this.verboseInfo('"Never" substitution entry found');
                this.updateSalesFromSalesItemSubstitute(itemSubNever);
                itemReplaced = true;
            }
            else
            {
                this.verboseInfo('"Never" substitution not found');
                
                // Check 4
                METSalesItemSubstitute itemSub;

                itemSub = this.findSalesItemSubstitute(
                    salesLine.ItemId,
                    METSalesItemSubstitutionCode::Replacement);

                if(!itemSub)
                {
                    this.verboseInfo('"Replacement" substitute not found');
                    itemSub = this.findSalesItemSubstitute(
                        salesLine.ItemId,
                        METSalesItemSubstitutionCode::OutOfStock);
                }
                
                if(itemSub)
                {
                    this.verboseInfo(strFmt('Replacement / Out of stock substitute found (%1)',
                        itemSub.description()));                   

                    Qty replacementItemOnHand = this.queryOnHandQty(
                        itemSub.SubstituteItemID, 
                        inventDim);
                   
                    // Assuming same inventory unit.. (EA) TODO confirm, what if different and no conversion?                    
                    if(replacementItemOnHand >= salesLine.QtyOrdered)
                    {
                        this.verboseInfo(strFmt('Replacement item on-hand is sufficient for ordered quantity'));


                    }
                    else
                    {
                        this.verboseInfo(strFmt('Replacement item on-hand is not sufficient for ordered quantity'));

                        // Check 6 - *** Spec refers to InventTransID = null but
                        // this will never be the case.

                        // Check 7
                        if(itemSub.OrderOriginalItem)
                        {
                            this.verboseInfo('Order original item set on substitute entry');
                            // "Order original item" applies. Do not replace item but mark
                            // sub details on line.
                            salesLine.METSubstituteReplacementItemID    = itemSub.SubstituteItemId;
                            salesLine.METSubstitutionCode               = itemSub.SubstitutionCode;
                        }
                        else
                        {
                            this.verboseInfo('Order original item is not set on substitute entry');
                            // Create new line
                        }

                        
                    }

                }
                else
                {
                    this.verboseInfo('No "Replacement" or "Out of stock" substitutions found');
                    salesLine.METSubstitutionCode = METSalesItemSubstitutionCode::OutOfStock;   // ** Confirm..
                }
                

            }
        }
        else
        {
            // Enough stock of ordered item. No further action required.
            this.verboseInfo(strFmt('On-hand qty of %1 is sufficient for ordered quantity of %2',
                onHandQty,
                salesLine.QtyOrdered));            
        }

        if(!bufCmp(salesLine, salesLine.orig()))
        {
            salesLine.update();
        }

        return ret;
    }

protected SalesLine copyToNewLine(ItemId _newItemId)
{
    SalesLine newLine;
    return newLine;
}

    protected Qty queryOnHandQty(ItemId _itemID, InventDim _inventDim)
    {
        InventDimParm   onHandDimParm;
        onHandDimParm.initFromInventDim(inventDim);
        InventOnhand    onHand = InventOnhand::newItemDim(_itemId, _inventDim, onHandDimParm);
        Qty             onHandQty;

        this.verboseInfo(strFmt('Checking on-hand for item %1',
            _itemID));
            
        if(CustParameters::find().METSubstitutionIncludeOnOrderInventory)
        {
            onHandQty = onHand.availOrdered(true);
            this.verboseInfo(strFmt('On-hand quantity including on-order is %1',
                onHandQty));
        }
        else
        {
            onHandQty = onHand.availPhysical();
            this.verboseInfo(strFmt('On-hand quantity (physical only) is %1',
                onHandQty));
        }
        return onHandQty;
    }

    /// <summary>
    /// Perform substitution checks/updates at point of order line entry. Relates to
    /// the "Always" substitution code or a "Parent/child" relationship.
    /// </summary>
    /// <param name = "_salesLine">_salesLine</param>
    /// <returns>Validation result</returns>
    protected boolean checkSalesLineAtCreation()
    {
        boolean                                 ret = true;

        METSalesItemSubstitute                  itemSub;
        METSalesItemSubstitutionParentChild     parentChild;
        
        select firstonly parentChild
            where   parentChild.InventSiteId    == salesTable.InventSiteId
            &&      parentChild.ChildItemID     == salesLine.ItemId;

        if(parentChild)
        {
            this.verboseInfo(strFmt('Parent/child relationship exists for child item %1 (Parent item %2)', 
                parentChild.ChildItemID,
                parentChild.ParentItemID));            

            if(this.yesNoPrompt(strFmt("Replace child item number %1 with Parent item number %2?",
                parentChild.ChildItemID,
                parentChild.ParentItemID)))
            {
                salesLine.ItemId                            = parentChild.ParentItemID;
                salesLine.METSubstituteOriginalItemID       = parentChild.ChildItemID;
                salesLine.METSubstituteReplacementItemID    = parentChild.ParentItemID;
                salesLine.METSubstituteParentItemID         = parentChild.ParentItemID; // *** Needed separately?
                salesLine.METSubstitutionType               = METSalesItemSubstitutionType::ParentChild;
                salesLine.METSubstitutionCode               = METSalesItemSubstitutionCode::None;
                salesLine.METSubstitutionSetupRefRecID      = parentChild.RecId;

                itemReplaced = true;                                
            }
            else
            {
                // Prompted for replacement based on parent/child but user cancelled updated.
                ret = checkFailed(strfmt("Item %1 cannot be selected as it has a parent/child substitution defined.", salesLine.ItemId));
            }
        }
        else
        {
            this.verboseInfo(strFmt('No Parent/child relationship exists for item %1', salesLine.ItemId));

            itemSub = this.findSalesItemSubstitute(
                salesLine.ItemId, 
                METSalesItemSubstitutionCode::Always);

            if(itemSub)
            {
                this.verboseInfo(strFmt('"Always" item substitution exists for item %1', salesLine.ItemId));

                if(this.yesNoPrompt(strFmt("Replace ordered item number %1 with substitute item number %2?",
                    parentChild.ChildItemID,
                    parentChild.ParentItemID)))
                {
                    this.updateSalesFromSalesItemSubstitute(itemSub);
                    itemReplaced = true;                    
                }
                else
                {
                    // Prompted for replacement based on 'Always' substitution but user did not confirm.
                    ret = checkFailed(strFmt("%1 cannot be selected as it has a substitution in place", salesLine.ItemId));
                }
            }
            else
            {
                this.verboseInfo('No matching substitute found with "Always" code');
            }
        }
        return ret;
    }

    protected METSalesItemSubstitute findSalesItemSubstitute(
        ItemId                              _itemID,
        METSalesItemSubstitutionCode        _subCode)  
    {
        this.verboseInfo(strFmt('Searching for substitute for item %1 (%2)',
            _itemID,
            _subCode));

        METSalesItemSubstitute itemSub;
        select firstonly itemSub
            order by AccountCode asc
            where   itemSub.ItemId              == _itemID
            &&      itemSub.InventSiteId        == salesTable.InventSiteId
            &&      itemSub.SubstitutionCode    == _subCode
            &&  (   // table/group/all match
                (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::Table &&
                    itemSub.AccountRelation == salesTable.CustAccount)
            ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::GroupId &&
                    itemSub.AccountRelation == substitutionGroup)
            ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::All &&
                    itemSub.AccountRelation == '')
            );
        return itemSub;
    }

protected void updateSalesFromSalesItemSubstitute(METSalesItemSubstitute _itemSub)
{
    salesLine.ItemId                            = _itemSub.SubstituteItemId;
    salesLine.METSubstituteOriginalItemID       = _itemSub.ItemId;
    salesLine.METSubstituteReplacementItemID    = _itemSub.SubstituteItemId;
    salesLine.METSubstituteParentItemID         = '';
    salesLine.METSubstitutionType               = METSalesItemSubstitutionType::SubstitutionCode;
    salesLine.METSubstitutionCode               = _itemSub.SubstitutionCode;
    salesLine.METSubstitutionSetupRefRecID      = _itemSub.RecId;
}

    /// <summary>
    /// Check and update quantity/unit if required.
    /// </summary>
    /// <returns></returns>
    protected boolean updateQuantity()
    {
        boolean             ret                     = true;
        InventTable         originalItem            = InventTable::find(salesLine.METSubstituteOriginalItemID);
        InventTableModule   originalItemInvent      = originalItem.inventTableModuleInvent();
        InventTable         replacementItem         = InventTable::find(salesLine.METSubstituteReplacementItemID);
        InventTableModule   replacementItemInvent   = replacementItem.inventTableModuleInvent();    
        InventTableModule   replacementItemSales    = replacementItem.inventTableModuleSales();

        this.verboseInfo(strFmt('Original item ordered quantity %1 of sales unit %2',
            salesLine.SalesQty,
            salesLine.SalesUnit));

        this.verboseInfo(strFmt('Original item ordered quantity %1 in inventory unit %2',
            salesLine.QtyOrdered,
            originalItemInvent.UnitId));

        this.verboseInfo(strFmt('Replacement item %1 has inventory unit %2, sales unit %3',
            replacementItem.ItemId,
            replacementItemInvent.UnitId,
            replacementItemSales.UnitId));

        if(originalItemInvent.UnitId == replacementItemInvent.UnitID)
        {
            Qty replacementQty = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                replacementItem.ItemId,
                InventDim::findOrCreate(inventDim).inventDimId,
                salesLine.QtyOrdered,
                replacementItemInvent.UnitId,
                replacementItemSales.UnitId,
                true,
                true);

            salesLine.SalesQty  = replacementQty;
            salesLine.SalesUnit = replacementItemSales.UnitId;  
          
            SalesLine::modifySalesQty(salesLine, inventDim);

            this.verboseInfo(strFmt('Conversion to %1 (%2) sales quantity',
                salesLine.SalesQty,
                salesLine.SalesUnit));
            this.verboseInfo(strFmt('Inventory quantity updated to %1 (%2) inventory quantity',
                salesLine.QtyOrdered,
                replacementItemInvent.UnitId));
        }
        else
        {
            // How to handle this scenario? (Item A and B don't have common inventory unit).
            this.verboseInfo(strFmt('Item %1 and %2 have different inventory units (%3 and %4). Unable to convert.',
                originalItem.ItemId,
                replacementItem.ItemId,
                originalItemInvent.UnitId,
                replacementItemInvent.UnitId));
        }
        return ret;       
    }

/// <summary>
/// Add verbose info to the log.
/// </summary>
/// <param name = "_msg">_msg</param>
private void verboseInfo(str _msg)
{
    if(this.verboseLogging)
    {
        METSalesItemSubstitutionVerboseLog verboseLog;
        verboseLog.SalesId         = salesTable.SalesId;
        verboseLog.Message         = _msg;
        verboseLog.TempReference   = salesLine.METSubstitutionVerboseLogReference;
        verboseLog.insert();
    }
}

/// <summary>
/// Prompt message with yes/no confirmation. If non-interactive, assume a 'Yes'
/// response. (eg via backend service/batch).
/// </summary>
/// <param name = "_msg"></param>
/// <returns></returns>
protected boolean yesNoPrompt(str _msg)
{
    if(interactive)
    {
        boolean promptRet = (Box::yesNo(_msg, DialogButton::No) == DialogButton::Yes);
        this.verboseInfo(promptRet ?
                'User confirmed replacement' :
                'User cancelled replacement');
        return promptRet;
    }
    else
    {
        this.verboseInfo('Replacement accepted without prompt (non-interactive)');
        return true;
    }
}

/// <summary>
/// Constructor
/// </summary>
private void new(
    SalesLine       _salesLine,
    InventDim       _inventDim)
{
    salesLine       = _salesLine;
    inventDim       = _inventDim;
    salesTable      = salesLine.salesTable();
}

    static public METSalesItemSubstitution construct(
        SalesLine                               _salesLine,
        InventDim                               _inventDim,
        METSalesItemSubstitutionEventSource     _eventSource,
        boolean                                 _interactive = true)
    {
        METSalesItemSubstitution sub = new METSalesItemSubstitution(
            _salesLine,
            _inventDim);
    
        sub.eventSource     = _eventSource;
        sub.interactive     = _interactive;

        return sub;
    }

    // ***************************************************

    /// <summary>
    /// SalesLine_onInserted
    /// </summary>
    /// <param name="sender">sender</param>
    /// <param name="e">e</param>
    [DataEventHandler(tableStr(SalesLine), DataEventType::Inserted)]
    public static void SalesLine_onInserted(Common sender, DataEventArgs e)
    {
        SalesLine salesLine = sender;

        METSalesItemSubstitutionVerboseLog::assignLotIDFromTempReference(
            salesLine.SalesId,
            salesLine.METSubstitutionVerboseLogReference,
            salesLine.InventTransId);  
    }
